// All implementations must embed UnimplementedThreadServiceServer
// for forward compatibility.
type ThreadServiceServer interface {
	CreateThread(context.Context, *CreateThreadRequest) (*CreateThreadResponse, error)
	GetThreadByID(context.Context, *GetThreadByIDRequest) (*GetThreadByIDResponse, error)
	UpdateThread(context.Context, *UpdateThreadRequest) (*Empty, error)
	DeleteThread(context.Context, *DeleteThreadRequest) (*Empty, error)
	ListThreads(context.Context, *ListThreadsRequest) (*ListThreadsResponse, error)
	ListThreadsByUserFollower(context.Context, *ListByUserRequest) (*ListThreadsResponse, error)
	ListThreadsByUser(context.Context, *ListByUserRequest) (*ListThreadsResponse, error)
	ListThreadsByCommunity(context.Context, *ListByCommunityRequest) (*ListThreadsResponse, error)
	SearchThreads(context.Context, *SearchThreadsRequest) (*SearchThreadsResponse, error)
	IncrementView(context.Context, *IncrementRequest) (*Empty, error)
	IncrementLike(context.Context, *IncrementRequest) (*Empty, error)
	IncrementComment(context.Context, *IncrementRequest) (*Empty, error)
	IncrementShare(context.Context, *IncrementRequest) (*Empty, error)
	CountThreads(context.Context, *Empty) (*CountThreadsResponse, error)
	// Likes
	LikeThread(context.Context, *ThreadUserRequest) (*Empty, error)
	UnlikeThread(context.Context, *ThreadUserRequest) (*Empty, error)
	CountThreadLikes(context.Context, *ThreadRequest) (*CountThreadsResponse, error)
	ListThreadsByUserLike(context.Context, *ListByUserRequest) (*ListThreadsResponse, error)
	ListThreadsByUserBookmark(context.Context, *ListByUserRequest) (*ListThreadsResponse, error)
	ListReplies(context.Context, *ListRepliesRequest) (*ListThreadsResponse, error)
	HasLikedThread(context.Context, *ThreadUserRequest) (*ExistsResponse, error)
	// Bookmarks
	BookmarkThread(context.Context, *ThreadUserRequest) (*Empty, error)
	UnbookmarkThread(context.Context, *ThreadUserRequest) (*Empty, error)
	CountThreadBookmarks(context.Context, *ThreadRequest) (*CountThreadsResponse, error)
	HasBookmarkedThread(context.Context, *ThreadUserRequest) (*ExistsResponse, error)
	CountThreadReplies(context.Context, *ThreadRequest) (*CountThreadsResponse, error)
	// Media attachments
	ListThreadMedia(context.Context, *ThreadRequest) (*ListThreadMediaResponse, error)
	AddThreadMedia(context.Context, *ThreadMediaRequest) (*Empty, error)
	RemoveThreadMedia(context.Context, *ThreadMediaRequest) (*Empty, error)
	CountThreadMedia(context.Context, *ThreadRequest) (*CountThreadsResponse, error)
	// Reply
	ListRepliesByUser(context.Context, *GetThreadByIDRequest) (*GetRepliesByIdResponse, error)
	GetMediaByUser(context.Context, *GetThreadByIDRequest) (*GetMediaByUserResponse, error)
	CreateCategory(context.Context, *CreateCategoryRequest) (*CreateCategoryResponse, error)
	ListCategories(context.Context, *Empty) (*ListCategoriesResponse, error)
	ListThreadsByCategory(context.Context, *ListThreadsByCategoryRequest) (*ListThreadsResponse, error)
	// Community Thread
	ListThreadsByCommunityByLike(context.Context, *ListThreadsByCommunityRequest) (*ListThreadsByCommunityResponse, error)
	ListThreadsByCommunityByTime(context.Context, *ListThreadsByCommunityRequest) (*ListThreadsByCommunityResponse, error)
	GetMediaByCommunity(context.Context, *GetMediaByCommunityRequest) (*GetMediaByCommunityResponse, error)
	CreateRepost(context.Context, *RepostThreadRequest) (*CreateThreadResponse, error)
	// Repost
	CountRepost(context.Context, *ThreadRequest) (*CountThreadsResponse, error)
	HasReposted(context.Context, *ThreadUserRequest) (*ExistsResponse, error)
	// Pin
	PinThread(context.Context, *ThreadRequest) (*Empty, error)
	// Thread Category
	UpdateCategory(context.Context, *UpdateCategoryRequest) (*Empty, error)
	DeleteCategory(context.Context, *DeleteCategoryRequest) (*Empty, error)
	// Thread Hashtag
	GetThreadsByHashtag(context.Context, *GetThreadsByHashtagRequest) (*GetThreadsByHashtagResponse, error)
	GetTopHashtags(context.Context, *GetTopHashtagsRequest) (*GetTopHashtagsResponse, error)
	// SearchThreads
	SearchThreadsByContent(context.Context, *SearchThreadsByContentRequest) (*SearchThreadsByContentResponse, error)
	// Explore Media
	SearchMediaByContent(context.Context, *SearchMediaByContentRequest) (*SearchMediaByContentResponse, error)
	mustEmbedUnimplementedThreadServiceServer()
}

